var n=`0523-joojeh-kebab`;var o=`world-0523`;var t=`IR`;var a=`western-asia`;var r=4;var s=181;var g={en:`Joojeh Kebab`,ua:`Джудже-кебаб`};var l={en:`A traditional dish from Iran, centered on chicken breast, lemon juice, plain yogurt, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: куряча грудка, лимонний сік, натуральний йогурт, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 150 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 150 хвилин.`,t:[`marinating`],m:150,i:[[`chicken-breast`,750,`g`],[`lemon-juice`,65,`ml`],[`extra-virgin-olive-oil`,60,`ml`],[`saffron-threads`,.4,`g`],[`plain-yogurt`,140,`g`],[`yellow-onion`,160,`g`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:10,i:[]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`tomato`,280,`g`]]}];var u={slug:n,id:o,country:`IR`,region:a,servings:4,minutes:181,title:g,text:l,steps:d};export{t as country,u as default,o as id,s as minutes,a as region,r as servings,n as slug,d as steps,l as text,g as title};